"""Private audio object storage and short-lived signed download links.

Development can use local disk (LocalObjectStore). Hosted DEV and production use a private S3-compatible
bucket (S3ObjectStore), while local disk is only private scratch space for validation before upload.

Protections:
* Storage keys are generated by the server from a hashed account id and a random object id. No client input
  ever reaches a path, and every key is checked against a strict pattern and resolved inside the root
  (defence in depth against path traversal and symlinks).
* Files and directories are created owner-only (0600 / 0700).
* Content is checked before commit: size limit and magic bytes matching the declared format.
* Download links are HMAC-signed, bound to one object and the owning account, and expire within minutes.
"""
import base64
import hashlib
import hmac
import json
import os
import re
import stat
import time
import uuid

FORMATS = {
    "wav": "audio/wav",
    "m4a": "audio/mp4",
    "mp3": "audio/mpeg",
}
_KEY = re.compile(r"^objects/[0-9a-f]{32}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(wav|m4a|mp3)$")
_TOKEN = re.compile(r"^[A-Za-z0-9_-]{16,400}\.[A-Za-z0-9_-]{43}$")


class StorageError(Exception):
    def __init__(self, code, message, diagnostic=None):
        super().__init__(code)
        self.code = code
        self.message = message
        # Safe, structured operator detail only. It is never returned by the HTTP API or included in __str__.
        self.diagnostic = diagnostic


def _storage_diagnostic(operation, error):
    """Extract only allow-listed S3 diagnostics; never retain exception text, URLs, headers or request data."""
    response = getattr(error, "response", {}) or {}
    try:
        status = int((response.get("ResponseMetadata") or {}).get("HTTPStatusCode"))
    except (TypeError, ValueError):
        status = getattr(error, "status", None)
    status = status if isinstance(status, int) and 0 <= status <= 599 else None
    raw_code = (response.get("Error") or {}).get("Code") or getattr(error, "safe_code", None)
    if isinstance(raw_code, str) and re.fullmatch(r"[A-Za-z0-9_.-]{1,64}", raw_code):
        safe_code = raw_code
    elif isinstance(error, AttributeError):
        safe_code = "ClientMethodMissing"
    elif isinstance(error, ImportError):
        safe_code = "DependencyMissing"
    else:
        name = type(error).__name__
        safe_code = name if re.fullmatch(r"[A-Za-z0-9_]{1,64}", name) else "UnknownClientError"
    category = getattr(error, "category", None)
    if category not in ("authentication", "access_denied", "dns", "tls", "timeout", "network",
                        "checksum", "dependency", "client", "service"):
        error_type = type(error).__name__
        if safe_code in ("InvalidAccessKeyId", "InvalidToken", "ExpiredToken", "SignatureDoesNotMatch",
                         "AuthFailure") or status == 401:
            category = "authentication"
        elif safe_code in ("AccessDenied", "Unauthorized") or status == 403:
            category = "access_denied"
        elif safe_code in ("BadDigest", "InvalidDigest", "XAmzContentSHA256Mismatch", "ChecksumError"):
            category = "checksum"
        elif error_type in ("SSLError", "SSLCertVerificationError"):
            category = "tls"
        elif error_type in ("ConnectTimeoutError", "ReadTimeoutError", "TimeoutError"):
            category = "timeout"
        elif error_type in ("EndpointConnectionError", "ConnectionClosedError"):
            category = "network"
        elif isinstance(error, ImportError):
            category = "dependency"
        else:
            category = "service" if status else "client"
    return {"operation": operation, "status": status, "code": safe_code, "category": category}


def _storage_unavailable(operation, error):
    return StorageError("STORAGE_UNAVAILABLE", "Private song storage is unavailable.",
                        diagnostic=_storage_diagnostic(operation, error))


def account_key(account):
    """Non-reversible per-account namespace used in storage keys and links (never the raw account id)."""
    return hashlib.sha256(("musicme-audio:" + str(account)).encode()).hexdigest()[:32]


def new_storage_key(account, object_id, fmt):
    if fmt not in FORMATS:
        raise StorageError("UNSUPPORTED_FORMAT", "Unsupported audio format.")
    key = f"objects/{account_key(account)}/{object_id}.{fmt}"
    if not _KEY.match(key):
        raise StorageError("INVALID_KEY", "Invalid storage key.")
    return key


def sniff_format(path):
    """Returns the audio format implied by the file's first bytes, or None."""
    with open(path, "rb") as f:
        head = f.read(12)
    if len(head) >= 12 and head[:4] == b"RIFF" and head[8:12] == b"WAVE":
        return "wav"
    if len(head) >= 8 and head[4:8] == b"ftyp":
        return "m4a"
    if head[:3] == b"ID3" or (len(head) >= 2 and head[0] == 0xFF and (head[1] & 0xE0) == 0xE0):
        return "mp3"
    return None


class LocalObjectStore:
    kind = "local"

    def __init__(self, root, max_bytes):
        os.makedirs(root, mode=0o700, exist_ok=True)
        self.root = os.path.realpath(root)
        self.max_bytes = max_bytes

    def _path(self, key):
        if not isinstance(key, str) or not _KEY.match(key):
            raise StorageError("INVALID_KEY", "Invalid storage key.")
        path = os.path.realpath(os.path.join(self.root, key))
        if os.path.commonpath([self.root, path]) != self.root:
            raise StorageError("INVALID_KEY", "Invalid storage key.")
        return path

    def temp_path(self, key):
        """A private scratch file next to the final location, so commit is an atomic rename."""
        final = self._path(key)
        directory = os.path.dirname(final)
        os.makedirs(directory, mode=0o700, exist_ok=True)
        return os.path.join(directory, f".tmp-{uuid.uuid4().hex}")

    def commit_file(self, temp, key, fmt):
        """Validates and atomically moves a rendered file into place. Returns (size, sha256)."""
        final = self._path(key)
        if os.path.dirname(os.path.realpath(temp)) != os.path.dirname(final):
            raise StorageError("INVALID_KEY", "Invalid temporary file.")
        info = os.lstat(temp)
        if not stat.S_ISREG(info.st_mode):
            raise StorageError("INVALID_CONTENT", "The audio output isn't a regular file.")
        size = os.path.getsize(temp)
        if size <= 0 or size > self.max_bytes:
            raise StorageError("INVALID_SIZE", "The audio file is empty or too large.")
        if sniff_format(temp) != fmt:
            raise StorageError("INVALID_CONTENT", "The audio file doesn't match its declared format.")
        digest = hashlib.sha256()
        with open(temp, "rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                digest.update(chunk)
        os.chmod(temp, 0o600)
        os.replace(temp, final)
        return size, digest.hexdigest()

    def open(self, key):
        return open(self._path(key), "rb")

    def exists(self, key):
        return os.path.isfile(self._path(key))

    def delete(self, key):
        """Unlinks the object. On SSDs and cloud stores, overwriting gives no extra guarantee, so secure deletion
        relies on owner-only permissions, deletion within the retention period and (in production) the provider's
        encrypted storage."""
        try:
            os.remove(self._path(key))
            return True
        except FileNotFoundError:
            return False

    def sweep_orphans(self, known_keys, older_than_seconds, now=None):
        """Deletes files (and stale temp files) that no database row knows about. Returns the number removed."""
        now = now or time.time()
        objects = os.path.join(self.root, "objects")
        removed = 0
        if not os.path.isdir(objects):
            return 0
        for directory, _, files in os.walk(objects):
            for name in files:
                path = os.path.join(directory, name)
                key = os.path.relpath(path, self.root).replace(os.sep, "/")
                if key in known_keys:
                    continue
                try:
                    if now - os.path.getmtime(path) >= older_than_seconds:
                        os.remove(path)
                        removed += 1
                except FileNotFoundError:
                    pass
        return removed

    def ready(self):
        return os.path.isdir(self.root) and os.access(self.root, os.R_OK | os.W_OK)


class S3ObjectStore:
    """Private S3-compatible song storage (AWS S3, Cloudflare R2, or another reviewed implementation).

    The bucket is never public. The API uploads only server-generated keys and streams objects through BeatIQ's
    account-bound links after checking ownership in PostgreSQL; no R2 URL reaches Android. Explicit credentials
    avoid an accidental instance-role or metadata-service fallback. A client may be injected for tests.
    """
    kind = "s3"

    def __init__(self, endpoint, bucket, region, access_key, secret_key, session_token, prefix, scratch_root,
                 max_bytes, force_path_style=False, client=None):
        self.endpoint, self.bucket, self.region = endpoint.rstrip("/"), bucket, region
        self.prefix = prefix.strip("/")
        self.max_bytes = max_bytes
        self.scratch_root = os.path.realpath(scratch_root)
        os.makedirs(self.scratch_root, mode=0o700, exist_ok=True)
        os.chmod(self.scratch_root, 0o700)
        if client is None:
            try:
                import boto3
                from botocore.config import Config
            except ImportError:
                raise SystemExit("S3-compatible storage requires boto3 (see requirements.txt).")
            client = boto3.client(
                "s3", endpoint_url=self.endpoint, region_name=self.region,
                aws_access_key_id=access_key, aws_secret_access_key=secret_key,
                aws_session_token=session_token or None,
                # Checksums only when an operation requires them: S3-compatible stores (e.g. R2) don't all accept the
                # SDK's default streaming checksums. Upload integrity is enforced explicitly with Content-MD5 below.
                config=Config(signature_version="s3v4", s3={"addressing_style": "path" if force_path_style else "virtual"},
                              retries={"max_attempts": 4, "mode": "standard"},
                              request_checksum_calculation="when_required", response_checksum_validation="when_required"),
            )
        self.client = client
        try:
            self.client.head_bucket(Bucket=self.bucket)
        except Exception as error:
            raise _storage_unavailable("head_bucket", error)

    def _remote_key(self, key):
        if not isinstance(key, str) or not _KEY.match(key):
            raise StorageError("INVALID_KEY", "Invalid storage key.")
        return f"{self.prefix}/{key}" if self.prefix else key

    def temp_path(self, key):
        self._remote_key(key)
        directory = os.path.join(self.scratch_root, "staging")
        os.makedirs(directory, mode=0o700, exist_ok=True)
        return os.path.join(directory, f".tmp-{uuid.uuid4().hex}")

    def commit_file(self, temp, key, fmt):
        remote = self._remote_key(key)
        operation = "put_object"
        try:
            info = os.lstat(temp)
        except FileNotFoundError:
            raise StorageError("INVALID_CONTENT", "The audio output is missing.")
        if not stat.S_ISREG(info.st_mode) or os.path.dirname(os.path.realpath(temp)) != os.path.join(self.scratch_root, "staging"):
            raise StorageError("INVALID_CONTENT", "The audio output isn't a valid private scratch file.")
        size = info.st_size
        if size <= 0 or size > self.max_bytes:
            raise StorageError("INVALID_SIZE", "The audio file is empty or too large.")
        if sniff_format(temp) != fmt:
            raise StorageError("INVALID_CONTENT", "The audio file doesn't match its declared format.")
        digest, md5 = hashlib.sha256(), hashlib.md5()  # MD5 only as the S3 Content-MD5 transfer check
        with open(temp, "rb") as source:
            for chunk in iter(lambda: source.read(1 << 20), b""):
                digest.update(chunk)
                md5.update(chunk)
        hexdigest = digest.hexdigest()
        try:
            # Single PUT (songs are capped far below the 5 GB single-object limit). The store recomputes Content-MD5
            # over the received bytes and rejects the upload on any mismatch, so a corrupted transfer never lands.
            with open(temp, "rb") as body:
                self.client.put_object(Bucket=self.bucket, Key=remote, Body=body, ContentLength=size,
                                       ContentType=FORMATS[fmt], ContentMD5=base64.b64encode(md5.digest()).decode(),
                                       Metadata={"sha256": hexdigest})
            operation = "head_object"
            head = self.client.head_object(Bucket=self.bucket, Key=remote)
            metadata = {str(k).lower(): str(v) for k, v in (head.get("Metadata") or {}).items()}
            if int(head.get("ContentLength", -1)) != size or not hmac.compare_digest(metadata.get("sha256", ""), hexdigest):
                self.client.delete_object(Bucket=self.bucket, Key=remote)
                raise StorageError("STORAGE_INTEGRITY", "Private song storage did not verify the upload.")
        except StorageError:
            raise
        except Exception as error:
            try:
                self.client.delete_object(Bucket=self.bucket, Key=remote)
            except Exception:
                pass
            raise _storage_unavailable(operation, error)
        return size, hexdigest

    def open(self, key):
        remote = self._remote_key(key)
        try:
            return self.client.get_object(Bucket=self.bucket, Key=remote)["Body"]
        except Exception as error:
            if _not_found(error):
                raise FileNotFoundError(key)
            raise _storage_unavailable("get_object", error)

    def exists(self, key):
        remote = self._remote_key(key)
        try:
            self.client.head_object(Bucket=self.bucket, Key=remote)
            return True
        except Exception as error:
            if _not_found(error):
                return False
            raise _storage_unavailable("head_object", error)

    def delete(self, key):
        remote = self._remote_key(key)
        try:
            self.client.delete_object(Bucket=self.bucket, Key=remote)
            return True
        except Exception as error:
            raise _storage_unavailable("delete_object", error)

    def sweep_orphans(self, known_keys, older_than_seconds, now=None):
        now = now or time.time()
        prefix = f"{self.prefix}/objects/" if self.prefix else "objects/"
        removed, token = 0, None
        operation = "list_objects_v2"
        try:
            while True:
                request = {"Bucket": self.bucket, "Prefix": prefix, "MaxKeys": 1000}
                if token:
                    request["ContinuationToken"] = token
                page = self.client.list_objects_v2(**request)
                for item in page.get("Contents") or []:
                    remote = item.get("Key", "")
                    key = remote[len(self.prefix) + 1:] if self.prefix else remote
                    modified = item.get("LastModified")
                    timestamp = modified.timestamp() if hasattr(modified, "timestamp") else float(modified or now)
                    if _KEY.match(key) and key not in known_keys and now - timestamp >= older_than_seconds:
                        operation = "delete_object"
                        self.client.delete_object(Bucket=self.bucket, Key=remote)
                        removed += 1
                        operation = "list_objects_v2"
                if not page.get("IsTruncated"):
                    break
                token = page.get("NextContinuationToken")
                if not token:
                    raise StorageError("STORAGE_UNAVAILABLE", "Private song storage pagination failed.")
        except StorageError:
            raise
        except Exception as error:
            raise _storage_unavailable(operation, error)
        return removed

    def ready(self):
        return True  # credentials and bucket access are verified synchronously during construction


def object_store_from_settings(settings, client=None):
    if settings.storage_backend == "local":
        return LocalObjectStore(settings.storage_root, settings.max_audio_bytes)
    return S3ObjectStore(
        settings.object_endpoint, settings.object_bucket, settings.object_region, settings.object_access_key_id,
        settings.object_secret_access_key, settings.object_session_token, settings.object_prefix,
        settings.storage_root, settings.max_audio_bytes, settings.object_force_path_style, client=client,
    )


def _not_found(error):
    response = getattr(error, "response", {}) or {}
    code = str((response.get("Error") or {}).get("Code", ""))
    status = (response.get("ResponseMetadata") or {}).get("HTTPStatusCode")
    return code in ("404", "NoSuchKey", "NotFound") or status == 404


def _b64(data):
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode()


def _unb64(text):
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


class LinkSigner:
    """Short-lived download links: base64url(payload).base64url(HMAC-SHA256(payload))."""

    def __init__(self, secret, ttl_seconds, clock=time.time):
        self._secret = secret.encode()
        self.ttl = ttl_seconds
        self.clock = clock

    def sign(self, object_id, account):
        expires = int(self.clock()) + self.ttl
        payload = _b64(json.dumps({"v": 1, "o": object_id, "k": account_key(account), "e": expires},
                                  separators=(",", ":")).encode())
        signature = _b64(hmac.new(self._secret, payload.encode(), hashlib.sha256).digest())
        return f"{payload}.{signature}", expires

    def verify(self, token):
        """Returns (object_id, account_key). Raises StorageError for anything forged, malformed or expired."""
        if not isinstance(token, str) or not _TOKEN.match(token):
            raise StorageError("LINK_INVALID", "This download link isn't valid.")
        payload, signature = token.split(".")
        expected = _b64(hmac.new(self._secret, payload.encode(), hashlib.sha256).digest())
        if not hmac.compare_digest(expected, signature):
            raise StorageError("LINK_INVALID", "This download link isn't valid.")
        try:
            claims = json.loads(_unb64(payload))
            object_id, key, expires = claims["o"], claims["k"], claims["e"]
        except Exception:
            raise StorageError("LINK_INVALID", "This download link isn't valid.")
        if claims.get("v") != 1 or not isinstance(expires, int) or not isinstance(object_id, str) or not isinstance(key, str):
            raise StorageError("LINK_INVALID", "This download link isn't valid.")
        if expires <= self.clock():
            raise StorageError("LINK_EXPIRED", "This download link has expired. Request a new one in the app.")
        return object_id, key
